class UserSearch
  SORTS = {
    "newest" => { created_at: :desc },
    "title" => { title: :asc }
  }.freeze

  def self.call(email:, sort: "newest")
    escaped = ActiveRecord::Base.sanitize_sql_like(email)
    order = SORTS.fetch(sort, SORTS.fetch("newest"))

    User.where("email LIKE ?", "%#{escaped}%")
        .order(order)
        .limit(50)
  end
end

